//! Pass 0 — the walk. Every Ruby file under the roots, in ordinal order, as
//! bytes: nothing is run, no bundle is read, and what the model writes of a
//! path is `/`-separated and root-relative on every OS.

use crate::model::utf16_cmp;
use std::fs;
use std::path::{Component, Path, PathBuf};

/// Third-party or generated by convention; a root named on the command line is
/// walked whatever it is called.
const SKIPPED_DIRECTORIES: &[&str] = &["node_modules", "vendor", "tmp"];
const EXTENSIONS: &[&str] = &["rb", "rake", "gemspec", "ru"];
/// Ruby files that carry no extension.
const BASENAMES: &[&str] = &[
    "Rakefile",
    "Gemfile",
    "Guardfile",
    "Capfile",
    "Vagrantfile",
    "Brewfile",
    "Dangerfile",
    "Thorfile",
];

pub struct SourceFile {
    /// Root-relative, `/`-separated.
    pub rel: String,
    pub source: Vec<u8>,
    /// Line count, at least 1: the file entity's anchor is `[1, lines]`.
    pub lines: u32,
}

pub struct Corpus {
    /// The header's `root`: the path as typed, or the common ancestor of several roots.
    pub root_display: String,
    pub files: Vec<SourceFile>,
}

pub fn slashes(path: &Path) -> String {
    path.to_string_lossy().replace('\\', "/")
}

/// Absolute and lexically normalised: no symlink is resolved, so the result
/// never depends on what the file system points at.
pub fn absolute(path: &str, cwd: &Path) -> PathBuf {
    let joined = if Path::new(path).is_absolute() {
        PathBuf::from(path)
    } else {
        cwd.join(path)
    };
    let mut out = PathBuf::new();
    for component in joined.components() {
        match component {
            Component::CurDir => {}
            Component::ParentDir => {
                out.pop();
            }
            other => out.push(other.as_os_str()),
        }
    }
    out
}

/// Deepest common ancestor of absolute directories — one root, no absolute anchor.
pub fn common_root(roots: &[PathBuf]) -> PathBuf {
    let mut common = roots[0].clone();
    for root in &roots[1..] {
        while !root.starts_with(&common) {
            if !common.pop() {
                break;
            }
        }
    }
    common
}

/// The typed path with `/` separators and no trailing slash.
fn display(typed: &str) -> String {
    let text = typed.replace('\\', "/");
    let trimmed = text.trim_end_matches('/');
    if trimmed.is_empty() {
        ".".to_owned()
    } else {
        trimmed.to_owned()
    }
}

fn is_ruby_file(name: &str) -> bool {
    match name.rsplit_once('.') {
        Some((stem, extension)) if !stem.is_empty() => EXTENSIONS.contains(&extension),
        _ => BASENAMES.contains(&name),
    }
}

/// `#!/usr/bin/env ruby` on an extensionless file: a script, by its own account.
fn has_ruby_shebang(path: &Path) -> bool {
    use std::io::Read;
    let mut head = [0u8; 96];
    let Ok(read) = fs::File::open(path).and_then(|mut file| file.read(&mut head)) else {
        return false;
    };
    let line = head[..read].split(|byte| *byte == b'\n').next().unwrap_or(&[]);
    line.starts_with(b"#!") && line.windows(4).any(|window| window == b"ruby")
}

fn walk(directory: &Path, out: &mut Vec<PathBuf>) -> Result<(), String> {
    let entries = fs::read_dir(directory).map_err(|e| format!("cannot read {}: {e}", slashes(directory)))?;
    for entry in entries {
        let entry = entry.map_err(|e| format!("cannot read {}: {e}", slashes(directory)))?;
        let path = entry.path();
        // A name that is not Unicode cannot enter a model; nothing Ruby loads is named so.
        let Some(name) = path.file_name().and_then(|n| n.to_str()).map(str::to_owned) else {
            continue;
        };
        let Ok(file_type) = entry.file_type() else { continue };
        if file_type.is_dir() {
            if !name.starts_with('.') && !SKIPPED_DIRECTORIES.contains(&name.as_str()) {
                walk(&path, out)?;
            }
        } else if is_ruby_file(&name) || (!name.contains('.') && has_ruby_shebang(&path)) {
            // A symlinked FILE is read; a symlinked directory is not followed (no cycles).
            if file_type.is_file() || fs::metadata(&path).map(|m| m.is_file()).unwrap_or(false) {
                out.push(path);
            }
        }
    }
    Ok(())
}

pub fn line_count(source: &[u8]) -> u32 {
    let newlines = source.iter().filter(|&&b| b == b'\n').count() as u32;
    let unterminated = matches!(source.last(), Some(&last) if last != b'\n');
    (newlines + u32::from(unterminated)).max(1)
}

pub fn load(sources: &[String], cwd: &Path) -> Result<Corpus, String> {
    let roots: Vec<PathBuf> = sources.iter().map(|source| absolute(source, cwd)).collect();
    for root in &roots {
        if !root.is_dir() {
            return Err(format!("source root is not a directory: {}", slashes(root)));
        }
    }
    let root = common_root(&roots);
    let root_display = match sources {
        [single] => display(single),
        _ => match root.strip_prefix(absolute(".", cwd)) {
            Ok(relative) => display(&slashes(relative)),
            Err(_) => slashes(&root),
        },
    };

    let mut found = Vec::new();
    for directory in &roots {
        walk(directory, &mut found)?;
    }
    let mut relative: Vec<(String, PathBuf)> = Vec::with_capacity(found.len());
    for full in found {
        let rel = full
            .strip_prefix(&root)
            .map_err(|_| format!("{} is not under the root", slashes(&full)))?;
        relative.push((slashes(rel), full));
    }
    // Ordinal order, never the file system's: the walk order IS the file table.
    relative.sort_by(|(a, _), (b, _)| utf16_cmp(a, b));
    relative.dedup_by(|(a, _), (b, _)| a == b);

    let mut files = Vec::with_capacity(relative.len());
    for (rel, full) in relative {
        let source = fs::read(&full).map_err(|e| format!("cannot read {rel}: {e}"))?;
        let lines = line_count(&source);
        files.push(SourceFile { rel, source, lines });
    }
    Ok(Corpus { root_display, files })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn walks_ruby_files_by_extension_and_by_name() {
        for name in [
            "order.rb",
            "db.rake",
            "acme.gemspec",
            "config.ru",
            "Rakefile",
            "Gemfile",
            "promo#2024.rb",
        ] {
            assert!(is_ruby_file(name), "{name}");
        }
        for name in [
            "README.md",
            "order.rb.bak",
            "console",
            ".rb",
            "rakefile.txt",
            "view.erb",
        ] {
            assert!(!is_ruby_file(name), "{name}");
        }
    }

    #[test]
    fn counts_lines_as_an_anchor_needs_them() {
        assert_eq!(line_count(b""), 1);
        assert_eq!(line_count(b"a"), 1);
        assert_eq!(line_count(b"a\n"), 1);
        assert_eq!(line_count(b"a\nb"), 2);
        assert_eq!(line_count(b"a\r\nb\r\n"), 2);
    }

    #[test]
    fn finds_the_deepest_common_ancestor_without_touching_the_disk() {
        let cwd = Path::new("/work/repo");
        assert_eq!(
            absolute("lib/../app/./models", cwd),
            PathBuf::from("/work/repo/app/models")
        );
        let roots = [
            absolute("app/models", cwd),
            absolute("app/controllers", cwd),
            absolute("lib", cwd),
        ];
        assert_eq!(common_root(&roots), PathBuf::from("/work/repo"));
        assert_eq!(common_root(&roots[..2]), PathBuf::from("/work/repo/app"));
        assert_eq!(display("fixtures/ruby/src/"), "fixtures/ruby/src");
        assert_eq!(display("./"), ".");
    }
}
